//! DEP-02 §Balance Commitments, against the shared vector
//! (`vectors/balance_commitments.txt`, generated by cl-deposits).
//!
//! Each step is an operation as first written and the same operation after the
//! operator declares its commitments; the declared one is applied as the update
//! at the step's height. Judge cases are operations judged on the final state
//! under a ruleset, for the commitment verdict alone.

use deposits_protocol::types::{
    with_apply_ctx, AllowAll, ApplyCtx, ConformanceViolation, LedgerState,
};
use deposits_protocol::{LedgerOperation, TlvDecode, TlvEncode};

fn ctx(height: u32, seq: u64) -> ApplyCtx {
    ApplyCtx {
        height,
        seq,
        ..ApplyCtx::default()
    }
}

fn verdict(state: &LedgerState, ruleset: &str, hex: &str, height: u32, seq: u64) -> String {
    let Ok(op) = LedgerOperation::tlv_decode(&hex::decode(hex).unwrap()) else {
        return "decode".into();
    };
    let mut s = state.clone();
    s.active_ruleset_name = ruleset.to_string();
    let violations = match with_apply_ctx(ctx(height, seq), || {
        s.apply_with_verifier(&op, &AllowAll, height)
    }) {
        Ok((_, v)) => v,
        Err(e) => return format!("other:{e}"),
    };
    if violations
        .iter()
        .any(|v| matches!(v, ConformanceViolation::BalanceCommitmentMismatch { .. }))
    {
        "mismatch".into()
    } else if violations
        .iter()
        .any(|v| matches!(v, ConformanceViolation::MissingBalanceCommitment { .. }))
    {
        "missing".into()
    } else {
        "ok".into()
    }
}

#[test]
fn balance_commitments_vector() {
    let pk = {
        use std::str::FromStr;
        bitcoin::secp256k1::PublicKey::from_str(
            "0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798",
        )
        .unwrap()
    };
    let mut state = LedgerState::new(pk, String::new(), 0);
    let (mut seq, mut steps, mut filled, mut judges) = (0u64, 0, 0, 0);
    for line in include_str!("vectors/balance_commitments.txt").lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let w: Vec<&str> = line.split(' ').collect();
        match w[0] {
            "step" => {
                steps += 1;
                if w[2] != w[3] {
                    filled += 1;
                }
                let height: u32 = w[1].parse().unwrap();
                let op = LedgerOperation::tlv_decode(&hex::decode(w[2]).unwrap()).unwrap();
                let out = state.fill_balance_commitments_at(op, height);
                assert_eq!(
                    hex::encode(out.tlv_encode()),
                    w[3],
                    "step {seq}: the declared commitments"
                );
                let declared = LedgerOperation::tlv_decode(&hex::decode(w[3]).unwrap()).unwrap();
                state = with_apply_ctx(ctx(height, seq), || state.apply(&declared))
                    .unwrap_or_else(|e| panic!("step {seq} applies: {e}"));
                seq += 1;
            }
            "judge" => {
                judges += 1;
                let height: u32 = w[2].parse().unwrap();
                assert_eq!(
                    verdict(&state, w[1], w[3], height, seq),
                    w[4],
                    "judge {} {}",
                    w[1],
                    &w[3][..16]
                );
            }
            other => panic!("unknown line kind {other}"),
        }
    }
    assert_eq!((steps, filled, judges), (27, 25, 29));
}
